from __future__ import annotations

import base64
import gzip
import json
import os
import shutil
import subprocess
import sys
import traceback
from datetime import datetime
from pathlib import Path

PROJECT = Path(os.environ.get("PHOCAP_PROJECT", r"C:\PhoCap")).resolve()
APP = PROJECT / "app"

USERS = APP / "routers" / "users.py"
LIST_TPL = APP / "templates" / "users" / "list.html"
PREVIEW_TPL = APP / "templates" / "users" / "bulk_level_all_preview.html"

PAYLOAD = {'app/routers/users.py': '', 'app/templates/users/list.html': '', 'app/templates/users/bulk_level_all_preview.html': ''}

STAMP = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP = PROJECT / "exports" / f"backup_bai_13b_6_v1_5_1_hien_nut_{STAMP}"
MANIFEST = BACKUP / "manifest.json"


def read(path: Path) -> str:
    if not path.exists():
        raise RuntimeError(f"Không tìm thấy: {path}")
    return path.read_text(encoding="utf-8-sig")


def backup() -> list[dict]:
    BACKUP.mkdir(parents=True, exist_ok=False)
    items = []
    for rel in PAYLOAD:
        src = PROJECT / rel
        existed = src.exists()
        items.append({"path": rel, "existed": existed})
        if existed:
            dst = BACKUP / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
    MANIFEST.write_text(json.dumps(items, ensure_ascii=False, indent=2), encoding="utf-8")
    return items


def restore(items: list[dict]) -> None:
    for item in reversed(items):
        target = PROJECT / item["path"]
        if item["existed"]:
            src = BACKUP / item["path"]
            if src.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, target)
        elif target.exists():
            target.unlink()


def preflight() -> None:
    users = read(USERS)
    tpl = read(LIST_TPL)

    if "BAI_13B_6_V1_4_TAI_KHOAN_TRUONG_THEO_CAP" not in users:
        raise RuntimeError(
            "Chưa tìm thấy nền tách tài khoản MN/TH/THCS. "
            "Dừng để không sửa nhầm source."
        )

    if "cap_hoc" not in tpl:
        raise RuntimeError("Template tài khoản hiện tại chưa có biến cap_hoc.")


def write_payload() -> None:
    for rel, encoded in PAYLOAD.items():
        target = PROJECT / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(gzip.decompress(base64.b64decode(encoded)))


def verify() -> None:
    subprocess.run([sys.executable, "-m", "py_compile", str(USERS)], cwd=PROJECT, check=True)

    from jinja2 import Environment, FileSystemLoader
    env = Environment(loader=FileSystemLoader(str(APP / "templates")))
    env.get_template("users/list.html")
    env.get_template("users/bulk_level_all_preview.html")

    users = read(USERS)
    tpl = read(LIST_TPL)

    for marker in [
        "BAI_13B_6_V1_5_CAP_TAT_CA_TAI_KHOAN_THEO_CAP",
        '@router.get("/cap-tat-ca-theo-cap"',
        '@router.post("/cap-tat-ca-theo-cap"',
    ]:
        if marker not in users:
            raise RuntimeError(f"users.py thiếu: {marker}")

    for marker in [
        "CẤP TÀI KHOẢN TOÀN CẤP",
        "Tạo tài khoản cho tất cả",
        "/tai-khoan/cap-tat-ca-theo-cap?cap={ cap_hoc }",
    ]:
        if marker not in tpl:
            raise RuntimeError(f"users/list.html thiếu: {marker}")


def main() -> int:
    print("=" * 96)
    print("BÀI 13B-6 V1.5.1 - HIỆN NÚT TẠO TÀI KHOẢN CHO TẤT CẢ")
    print("=" * 96)
    print("")
    print("Sửa đúng lỗi: trang TK trường Tiểu học/THCS đã tách đúng nhưng chưa thấy nút.")
    print("Nút sẽ hiện ngay trên trang có cap=MN / TH / THCS.")
    print("Backend vẫn kiểm tra quyền Quản trị và có bước xem trước trước khi tạo.")
    print("")

    preflight()
    items = backup()

    try:
        write_payload()
        verify()

        for cache in APP.rglob("__pycache__"):
            if cache.is_dir():
                shutil.rmtree(cache, ignore_errors=True)

        print("")
        print("CAI DAT BAI 13B-6 V1.5.1 HIEN NUT CAP TAT CA THANH CONG")
        print("Backup:", BACKUP)
        return 0
    except Exception:
        traceback.print_exc()
        restore(items)
        print("")
        print("CÓ LỖI - ĐÃ KHÔI PHỤC TỰ ĐỘNG.")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
